input.command:
cat > config.json << 'EOF'
{
  "name": "GraphQL Migration RFC",
  "description": "Technical RFC proposing switch from REST to GraphQL for client-facing APIs, covering pain points, proposed approach, schema sketch for projects/tasks, and open questions."
}
EOF

mkdir -p agents
cat > config.json << 'EOF'
{
  "name": "GraphQL RFC API Design Review",
  "description": "Structured review of the GraphQL migration RFC evaluating schema complexity, query depth limits, pagination strategy, error handling conventions, backward compatibility with REST clients, with verdicts and overall recommendation."
}
EOF
cat > topology.json << 'EOF'
{
  "agents": {
    "reviewer": { "depends_on": [] }
  }
}
EOF
cat > agents/reviewer.json << 'EOF'
{
  "name": "API Design Reviewer",
  "system_prompt": "Senior API architect expert in GraphQL. Review RFCs for schema design, performance, usability, error handling, and compatibility best practices.",
  "assignment": "Read the GraphQL Migration RFC from the previous step. Evaluate from an API design perspective: schema complexity, query depth limits, pagination strategy, error handling conventions, and backward compatibility with existing REST clients. For each area give a verdict (approve / concern / block) with a one-sentence rationale. End with an overall recommendation.",
  "expected_output": "Where you saved the review report. List verdicts for each area and the overall recommendation.",
  "capabilities": []
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL Performance Review",
  "description": "Performance audit of GraphQL migration RFC: N+1 query risks, payload sizes vs REST, caching strategies (CDN/persisted queries/dataloader), latency estimates, with per-area verdicts and overall recommendation."
}
EOF

cat > config.json << 'EOF'
{
  "name": "GraphQL Security Review",
  "description": "Security audit of GraphQL RFC evaluating query complexity limits, authorization model, introspection exposure, rate limiting, custom scalar injections; provides per-area verdicts and overall recommendation."
}
EOF

mkdir -p agents
cat > config.json << 'EOF'
{
  "name": "DX Review of GraphQL RFC",
  "description": "Evaluation of GraphQL Migration RFC from frontend developer experience perspective: client code generation, type safety vs REST, documentation tooling, testing strategy, migration burden, with verdicts per area and overall recommendation."
}
EOF
cat > topology.json << 'EOF'
{
  "agents": {
    "reviewer": { "depends_on": [] }
  }
}
EOF
cat > agents/reviewer.json << 'EOF'
{
  "name": "DX Reviewer",
  "system_prompt": "Frontend DX specialist. Review API RFCs for client-side developer experience, focusing on codegen, type safety, docs, testing, and migration.",
  "assignment": "Read the GraphQL Migration RFC from the previous step. Evaluate: client code generation workflow, type safety improvements over REST, documentation tooling (playground, schema docs), testing strategy (mocking, integration tests), migration burden for frontend teams. Provide a verdict (strong yes/neutral/no) per area with reasoning, and an overall recommendation.",
  "expected_output": "Review report saved where? Structure: sections per evaluation area, verdicts, overall rec. Word count.",
  "capabilities": []
}
EOF

mkdir -p agents
cat > config.json << 'EOF'
{
  "name": "Review Synthesis",
  "description": "Synthesizes API Design, Performance, and Security reviews of GraphQL RFC into a conflict resolution document. Produces a table comparing verdicts per area, with resolutions for disagreements and action items."
}
EOF
cat > topology.json << 'EOF'
{
  "agents": {
    "synthesizer": { "depends_on": [] }
  }
}
EOF
cat > agents/synthesizer.json << 'EOF'
{
  "name": "Synthesizer",
  "system_prompt": "Review synthesizer. Merge multi-domain technical feedback into consensus docs, resolving conflicts with reasoned proposals.",
  "assignment": "Read the upstream GraphQL RFC reviews: API Design, Performance, Security. Align areas covered. For each area, extract verdicts. Summarize agreements; for disagreements, state conflict and propose resolution. Produce markdown table: | Area | API Verdict | Perf Verdict | Security Verdict | Resolution | Action Item |. Include overall recommendation.",
  "expected_output": "Table saved to e.g. resolution_table.md. Areas covered, conflicts found, resolutions proposed, file location.",
  "capabilities": []
}
EOF

mkdir -p agents
cat > config.json << 'EOF'
{
  "name": "GraphQL Migration Plan",
  "description": "A phased migration plan from REST to GraphQL based on DX review, structured as a timeline with deliverables, team responsibilities, rollback triggers, and success metrics for each phase."
}
EOF
cat > topology.json << 'EOF'
{
  "agents": {
    "planner": { "depends_on": [] }
  }
}
EOF
cat > agents/planner.json << 'EOF'
{
  "name": "Migration Planner",
  "system_prompt": "API migration specialist. Design phased rollout plans for backend changes, incorporating DX feedback, with clear deliverables, responsibilities, risks, and metrics.",
  "assignment": "Read the DX review from the previous step. Create a phased migration plan from REST to GraphQL: Phase 1 dual-running (4 weeks), Phase 2 new endpoints GraphQL-only (4 weeks), Phase 3 REST deprecation (8 weeks). For each phase, detail deliverables, team responsibilities, rollback triggers, success metrics. Output as a structured timeline.",
  "expected_output": "Migration plan filename, total phases covered, key deliverables listed, where saved.",
  "capabilities": []
}
EOF

mkdir -p agents
cat > config.json << 'EOF'
{
  "name": "GraphQL Migration ADR",
  "description": "Formal Architecture Decision Record (ADR) for GraphQL adoption over REST. Uses standard format: Title, Status (proposed), Context, Decision, Consequences (positive/negative), Compliance, Migration Reference linking phases to consequences. Cross-references conflict resolution table and migration timeline."
}
EOF
cat > topology.json << 'EOF'
{
  "agents": {
    "adr_writer": { "depends_on": [] }
  }
}
EOF
cat > agents/adr_writer.json << 'EOF'
{
  "name": "ADR Writer",
  "system_prompt": "ADR specialist. Synthesize technical reviews, resolutions, and migration plans into formal Architecture Decision Records.",
  "assignment": "Read the GraphQL Migration Plan and Review Synthesis from previous steps. Write a formal ADR titled 'Adopt GraphQL API replacing REST' with Status: proposed. Include Context from reviews and resolutions, Decision to proceed with mitigations, positive/negative Consequences, Compliance enforcement plan, and Migration Reference linking plan phases to consequences. Cross-reference the conflict resolution table and migration timeline by name.",
  "expected_output": "ADR filename and path, title, status, summary of key sections (Context, Decision, Consequences, Compliance, Migration Reference), and how it references upstream artifacts.",
  "capabilities": []
}
EOF
